CREATE SEQUENCE account_number_seq START 1000;
CREATE TABLE app_user(id uuid PRIMARY KEY, email varchar(254) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, account_number bigint NOT NULL UNIQUE, role varchar(20) NOT NULL CHECK(role IN ('CUSTOMER','ADMIN','SALES','SUPPORT')), enabled boolean NOT NULL DEFAULT true, security_version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL, last_access timestamptz);
CREATE TABLE auth_session(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,security_version bigint NOT NULL,created_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,last_used timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false);
CREATE TABLE refresh_token(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES auth_session, digest varchar(64) NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed boolean NOT NULL DEFAULT false);
CREATE TABLE reset_token(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,digest varchar(64) NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed boolean NOT NULL DEFAULT false);
CREATE TABLE product(id uuid PRIMARY KEY,sku varchar(80) NOT NULL UNIQUE,manufacturer varchar(80) NOT NULL,model varchar(120) NOT NULL,category varchar(20) NOT NULL CHECK(category IN ('PC','LAPTOP','TABLET','ACCESSORY')),condition varchar(10) NOT NULL CHECK(condition IN ('NEW','USED')),cpu varchar(120),ram varchar(80),storage varchar(120),gpu varchar(120),os varchar(120),price numeric(12,2) NOT NULL CHECK(price>0),stock integer NOT NULL CHECK(stock>=0),active boolean NOT NULL,description varchar(2000) NOT NULL,reorder_point integer NOT NULL DEFAULT 100,reorder_quantity integer NOT NULL DEFAULT 100,version bigint NOT NULL DEFAULT 0,CHECK(category<>'ACCESSORY' OR condition='NEW'));
CREATE TABLE cart_line(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,product_id uuid NOT NULL REFERENCES product,quantity integer NOT NULL CHECK(quantity>0),UNIQUE(user_id,product_id));
CREATE TABLE customer_profile(user_id uuid PRIMARY KEY REFERENCES app_user,kind varchar(20) NOT NULL CHECK(kind IN ('INDIVIDUAL','BUSINESS')),business_name varchar(160),version bigint NOT NULL DEFAULT 0);
CREATE TABLE contact(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,type char(1) NOT NULL CHECK(type IN ('P','A')),first_name varchar(80) NOT NULL,last_name varchar(80) NOT NULL,email varchar(254) NOT NULL,phone varchar(40) NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(user_id,type));
CREATE TABLE address(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,type char(1) NOT NULL CHECK(type IN ('M','S')),line1 varchar(160) NOT NULL,line2 varchar(160),city varchar(100) NOT NULL,state char(2) NOT NULL,zip varchar(10) NOT NULL,country char(2) NOT NULL CHECK(country='US'),UNIQUE(user_id,type));
CREATE TABLE customer_order(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,order_number varchar(40) NOT NULL UNIQUE,status varchar(30) NOT NULL CHECK(status IN ('CONFIRMED','PAYMENT_FAILED','PROCESSING','SHIPPED')),subtotal numeric(12,2) NOT NULL,shipping numeric(12,2) NOT NULL,tax numeric(12,2) NOT NULL,total numeric(12,2) NOT NULL,shipping_snapshot text NOT NULL,contact_snapshot text NOT NULL,created_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 0,tracking varchar(160));
CREATE INDEX orders_customer_date ON customer_order(user_id,created_at DESC);
CREATE TABLE order_line(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES customer_order,product_id uuid NOT NULL REFERENCES product,sku varchar(80) NOT NULL,description varchar(2000) NOT NULL,condition varchar(10) NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price numeric(12,2) NOT NULL);
CREATE TABLE payment_attempt(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES customer_order,method varchar(30) NOT NULL,status varchar(20) NOT NULL,transaction_ref varchar(80) NOT NULL UNIQUE,amount numeric(12,2) NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE checkout_quote(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,digest varchar(64) NOT NULL,snapshot text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE idempotency_record(user_id uuid NOT NULL REFERENCES app_user,key varchar(100) NOT NULL,digest varchar(64) NOT NULL,order_id uuid NOT NULL REFERENCES customer_order,PRIMARY KEY(user_id,key));
CREATE TABLE stock_movement(id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES product,reference varchar(100) NOT NULL,delta integer NOT NULL,reason varchar(200) NOT NULL,created_at timestamptz NOT NULL,UNIQUE(product_id,reference));
CREATE TABLE replenishment_request(id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES product,quantity integer NOT NULL CHECK(quantity>0),status varchar(20) NOT NULL,created_at timestamptz NOT NULL,dispatched_at timestamptz,received_at timestamptz);
CREATE UNIQUE INDEX one_open_reorder ON replenishment_request(product_id) WHERE status<>'RECEIVED';
CREATE TABLE audit_event(id uuid PRIMARY KEY,actor uuid,action varchar(80) NOT NULL,entity varchar(100) NOT NULL,correlation_id varchar(100),created_at timestamptz NOT NULL);
CREATE TABLE outbox(id uuid PRIMARY KEY,kind varchar(40) NOT NULL,payload text NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,next_attempt timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL,completed_at timestamptz);
CREATE TABLE mail_sink(id uuid PRIMARY KEY,recipient varchar(254) NOT NULL,subject varchar(160) NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE contact_inquiry(id uuid PRIMARY KEY,email varchar(254) NOT NULL,phone varchar(40) NOT NULL,reason varchar(30) NOT NULL,message varchar(500) NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE rate_limit(key varchar(300) PRIMARY KEY,attempts integer NOT NULL,window_end timestamptz NOT NULL);
CREATE INDEX catalog_filters ON product(active,category,manufacturer);
CREATE INDEX pending_outbox ON outbox(next_attempt) WHERE status='PENDING';
GRANT USAGE ON SCHEMA public TO np_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO np_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO np_app;
REVOKE UPDATE,DELETE ON audit_event FROM np_app;
